    """
    def to_float(val):
        if isinstance(val, (int, float)):
            return float(val)
        if isinstance(val, str):
            # Replace comma with dot to handle European decimal format
            return float(val.replace(',', '.'))
        return val

    val_a = to_float(a)
    val_b = to_float(b)

    if val_a == val_b:
        return None
    elif val_a > val_b:
        return a
    else:
        return b
