from typing import List

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        MAX_VAL = 100001
        min_idx_for_val = [-1] * MAX_VAL
        for j, val in enumerate(elements):
            if val < MAX_VAL:
                if min_idx_for_val[val] == -1:
                    min_idx_for_val[val] = j

        res_idx = [-1] * MAX_VAL

        # To ensure we get the smallest index efficiently, we can iterate through
        # all possible values 'v' and for each 'v' that is in elements, 
        # update its multiples.
        # The complexity is O(V log V) where V = 10^5.
        for v in range(1, MAX_VAL):
            idx = min_idx_for_val[v]
            if idx != -1:
                for multiple in range(v, MAX_VAL, v):
                    if res_idx[multiple] == -1 or idx < res_idx[multiple]:
                        res_idx[multiple] = idx

        return [res_idx[g] for g in groups]

