class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]

        # Base Case
        v00 = coins[0][0]
        dp[0][0][0] = v00
        if v00 < 0:
            dp[0][0][1] = 0
            dp[0][0][2] = 0
        else:
            dp[0][0][1] = v00
            dp[0][0][2] = v00

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0: continue
                v = coins[i][j]

                # k = 0
                prev0 = -float('inf')
                if i > 0: prev0 = max(prev0, dp[i-1][j][0])
                if j > 0: prev0 = max(prev0, dp[i][j-1][0])
                if prev0 != -float('inf'):
                    dp[i][j][0] = prev0 + v

                # k = 1
                # Case 1: 1 neutralization used before this cell
                prev1 = -float('inf')
                if i > 0: prev1 = max(prev1, dp[i-1][j][1])
                if j > 0: prev1 = max(prev1, dp[i][j-1][1])
                if prev1 != -float('inf'):
                    dp[i][j][1] = prev1 + v
                # Case 2: 1st neutralization used at this cell
                if v < 0:
                    prev0_for_1 = -float('inf')
                    if i > 0: prev0_for_1 = max(prev0_for_1, dp[i-1][j][0])
                    if j > 0: prev0_for_1 = max(prev0_for_1, dp[i][j-1][0])
                    if prev0_for_1 != -float('inf'):
                        dp[i][j][1] = max(dp[i][j][1], prev0_for_1)

                # k = 2
                # Case 1: 2 neutralizations used before this cell
                prev2 = -float('inf')
                if i > 0: prev2 = max(prev2, dp[i-1][j][2])
                if j > 0: prev2 = max(prev2, dp[i][j-1][2])
                if prev2 != -float('inf'):
                    dp[i][j][2] = prev2 + v
